//! Server-side re-query of the table tab (decision 10, second half):
//! per-column sorting and filters become `ORDER BY` / `WHERE` generated
//! here, with the dialect's quoting. In the table tab it is the click on the
//! header (Shift = one more column); the local sort on a permutation (§4.8)
//! stays a separate gesture, from the header menu.
//!
//! The SQL is still generated by the app: the no-rewrite rule (§5.2) applies
//! to the *user's* SQL. Column names come from the result set schema or from
//! introspection and go through `quote_identifier` anyway; values go through
//! `quote_string_literal` (per-dialect escaping — on MySQL the backslash
//! too). The text-against-number comparison is resolved by the server: an
//! invalid literal produces a SQL error that the UI shows with the pipeline
//! of §6.

use alamo_core::dialect::Dialect;
use serde::Deserialize;

/// Sorting and filters requested by the UI for a table tab.
#[derive(Debug, Clone, Default, Deserialize)]
pub struct TableQuery {
    /// Columns of the `ORDER BY`, in priority order. Empty = no sorting
    /// (the server decides the order).
    #[serde(default, deserialize_with = "one_or_many")]
    pub order_by: Vec<OrderBy>,
    #[serde(default)]
    pub filters: Vec<ColumnFilter>,
    /// Condition written by hand by the user (WHERE bar, like DBeaver),
    /// ANDed with the chip filters. Empty = none. It is user SQL inside an
    /// app SELECT: it is not rewritten, but before executing it
    /// `Session::check_table_query` verifies that it stays a single statement
    /// and, on read-only profiles, that it does not write.
    #[serde(default)]
    pub where_sql: String,
}

/// `order_by` was a single object (or `null`) before multi-column sort:
/// both forms are still accepted, besides the list.
fn one_or_many<'de, D: serde::Deserializer<'de>>(d: D) -> Result<Vec<OrderBy>, D::Error> {
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum Form {
        Many(Vec<OrderBy>),
        One(OrderBy),
    }
    Ok(match Option::<Form>::deserialize(d)? {
        None => Vec::new(),
        Some(Form::One(o)) => vec![o],
        Some(Form::Many(v)) => v,
    })
}

#[derive(Debug, Clone, Deserialize)]
pub struct OrderBy {
    pub column: String,
    #[serde(default)]
    pub desc: bool,
}

#[derive(Debug, Clone, Deserialize)]
pub struct ColumnFilter {
    pub column: String,
    pub op: FilterOp,
    /// Ignored by the operators without an operand (`IS NULL` / `IS NOT NULL`).
    #[serde(default)]
    pub value: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum FilterOp {
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
    Like,
    NotLike,
    IsNull,
    IsNotNull,
}

impl FilterOp {
    fn sql(self) -> &'static str {
        match self {
            FilterOp::Eq => "=",
            FilterOp::Ne => "<>",
            FilterOp::Lt => "<",
            FilterOp::Le => "<=",
            FilterOp::Gt => ">",
            FilterOp::Ge => ">=",
            FilterOp::Like => "LIKE",
            FilterOp::NotLike => "NOT LIKE",
            FilterOp::IsNull => "IS NULL",
            FilterOp::IsNotNull => "IS NOT NULL",
        }
    }

    fn takes_value(self) -> bool {
        !matches!(self, FilterOp::IsNull | FilterOp::IsNotNull)
    }
}

/// Column → value for the `UPDATE` of grid editing (M4). Values come from
/// the row cache as canonical strings; the cast is done by the server, as
/// for the filters (an invalid literal = SQL error in the UI).
#[derive(Debug, Clone, Deserialize)]
pub struct CellAssign {
    pub column: String,
    /// `None` = SQL `NULL` (in WHERE it becomes `IS NULL`).
    #[serde(default)]
    pub value: Option<String>,
    /// SET only: `col = DEFAULT`, the column default decided by the server
    /// (`value` ignored). Never in a key.
    #[serde(default)]
    pub default: bool,
    /// The column holds numbers: in SET / VALUES the value goes bare when
    /// it looks like a number (`flag = 1`), quoted otherwise so that the
    /// server's own error says what is wrong. MySQL `BIT` needs it: `'1'`
    /// into a BIT is the byte 0x31, "Data too long" — `1` is the bit. In
    /// the WHERE the quoted form compares fine on every type, it stays.
    #[serde(default)]
    pub numeric: bool,
}

/// Value of a SET / VALUES assignment, see `CellAssign::numeric`.
fn assigned_literal(dialect: &dyn Dialect, a: &CellAssign, v: &str) -> String {
    if a.numeric && is_number_literal(v) {
        v.to_string()
    } else {
        dialect.quote_string_literal(v)
    }
}

/// `-?digits(.digits)?` — the only form sent bare; anything else keeps the
/// quotes (and the server's error).
fn is_number_literal(v: &str) -> bool {
    let v = v.strip_prefix('-').unwrap_or(v);
    let (int, frac) = match v.split_once('.') {
        Some((i, f)) => (i, Some(f)),
        None => (v, None),
    };
    let digits = |s: &str| !s.is_empty() && s.bytes().all(|b| b.is_ascii_digit());
    digits(int) && frac.map_or(true, digits)
}

/// A saved row to write back into an open result set without a query
/// (§9.5.1): the key values as the grid holds them, and the cells by
/// result column index.
#[derive(Debug, Clone, Deserialize)]
pub struct PatchRow {
    pub key: Vec<Option<String>>,
    pub set: Vec<(usize, Option<String>)>,
}

/// One row of the multi-cell batch (decision 12, single rectangle):
/// SET of the touched cells + PK key of the row. Same shape as single-cell
/// editing, in bulk.
#[derive(Debug, Clone, Deserialize)]
pub struct RowUpdate {
    pub set: Vec<CellAssign>,
    pub key: Vec<CellAssign>,
}

/// One write of the table tab batch. UPDATEs are cell editing (decision 12);
/// INSERTs are the new rows ("+ Row" / "Duplicate", like DBeaver); DELETEs
/// the deleted rows. Execution order in the batch: DELETE, UPDATE, INSERT —
/// a PK freed by a DELETE or an UPDATE is immediately reusable afterwards.
#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum TableWrite {
    Update {
        set: Vec<CellAssign>,
        key: Vec<CellAssign>,
    },
    /// New row: the columns not listed are filled by the server with their
    /// default. Empty = row entirely at default.
    Insert { values: Vec<CellAssign> },
    /// Deleted row, by PK key (like the UPDATE, never without a key).
    Delete { key: Vec<CellAssign> },
}

impl From<RowUpdate> for TableWrite {
    fn from(u: RowUpdate) -> Self {
        TableWrite::Update {
            set: u.set,
            key: u.key,
        }
    }
}

impl TableWrite {
    pub(crate) fn sql(&self, dialect: &dyn Dialect, schema: &str, table: &str) -> String {
        match self {
            TableWrite::Update { set, key } => update_sql(dialect, schema, table, set, key),
            TableWrite::Insert { values } => insert_sql(dialect, schema, table, values),
            TableWrite::Delete { key } => delete_sql(dialect, schema, table, key),
        }
    }
}

/// `INSERT` of a new row. DEFAULT columns are written explicitly
/// (`DEFAULT` in the VALUES) so that the preview says what happens; with no
/// columns at all the form depends on the dialect: `DEFAULT VALUES` on
/// PostgreSQL, `() VALUES ()` on MySQL/MariaDB.
pub(crate) fn insert_sql(
    dialect: &dyn Dialect,
    schema: &str,
    table: &str,
    values: &[CellAssign],
) -> String {
    let mut sql = format!(
        "INSERT INTO {}.{}",
        dialect.quote_identifier(schema),
        dialect.quote_identifier(table)
    );
    if values.is_empty() {
        sql.push_str(if dialect.capabilities().supports_default_values {
            " DEFAULT VALUES"
        } else {
            " () VALUES ()"
        });
        return sql;
    }
    sql.push_str(" (");
    for (i, a) in values.iter().enumerate() {
        if i > 0 {
            sql.push_str(", ");
        }
        sql.push_str(&dialect.quote_identifier(&a.column));
    }
    sql.push_str(") VALUES (");
    for (i, a) in values.iter().enumerate() {
        if i > 0 {
            sql.push_str(", ");
        }
        match &a.value {
            _ if a.default => sql.push_str("DEFAULT"),
            Some(v) => sql.push_str(&assigned_literal(dialect, a, v)),
            None => sql.push_str("NULL"),
        }
    }
    sql.push(')');
    sql
}

/// `DELETE` of a row identified by the primary key. Same WHERE as the
/// UPDATE: one row per statement, never a mass deletion.
pub(crate) fn delete_sql(
    dialect: &dyn Dialect,
    schema: &str,
    table: &str,
    key: &[CellAssign],
) -> String {
    let mut sql = format!(
        "DELETE FROM {}.{}",
        dialect.quote_identifier(schema),
        dialect.quote_identifier(table)
    );
    for (i, k) in key.iter().enumerate() {
        sql.push_str(if i == 0 { " WHERE " } else { " AND " });
        sql.push_str(&dialect.quote_identifier(&k.column));
        match &k.value {
            Some(v) => {
                sql.push_str(" = ");
                sql.push_str(&dialect.quote_string_literal(v));
            }
            None => sql.push_str(" IS NULL"),
        }
    }
    sql
}

/// `SELECT *` of the row just inserted, where there is no `RETURNING`: by
/// key if the INSERT wrote all of it, otherwise with `LAST_INSERT_ID()` if
/// the key is a single column (auto_increment). `None` = no way to re-read
/// it (composite key at default, no key): the UI reloads.
pub(crate) fn reread_inserted_sql(
    dialect: &dyn Dialect,
    schema: &str,
    table: &str,
    values: &[CellAssign],
    key_columns: &[String],
) -> Option<String> {
    if key_columns.is_empty() {
        return None;
    }
    let mut sql = format!(
        "SELECT * FROM {}.{} WHERE ",
        dialect.quote_identifier(schema),
        dialect.quote_identifier(table)
    );
    let given: Vec<&CellAssign> = key_columns
        .iter()
        .filter_map(|k| values.iter().find(|a| &a.column == k && !a.default))
        .collect();
    if given.len() == key_columns.len() {
        for (i, a) in given.iter().enumerate() {
            if i > 0 {
                sql.push_str(" AND ");
            }
            sql.push_str(&dialect.quote_identifier(&a.column));
            match &a.value {
                Some(v) => {
                    sql.push_str(" = ");
                    sql.push_str(&dialect.quote_string_literal(v));
                }
                None => sql.push_str(" IS NULL"),
            }
        }
        return Some(sql);
    }
    if key_columns.len() == 1 {
        sql.push_str(&dialect.quote_identifier(&key_columns[0]));
        sql.push_str(" = LAST_INSERT_ID()");
        return Some(sql);
    }
    None
}

/// `UPDATE` of a row identified by the primary key (decision 6: without a
/// PK the grid stays read-only and we never get here). Deterministic
/// generation: the preview shown at confirmation and the executed SQL both
/// come out of here, from the same parameters.
pub(crate) fn update_sql(
    dialect: &dyn Dialect,
    schema: &str,
    table: &str,
    set: &[CellAssign],
    key: &[CellAssign],
) -> String {
    let mut sql = format!(
        "UPDATE {}.{} SET ",
        dialect.quote_identifier(schema),
        dialect.quote_identifier(table)
    );
    for (i, a) in set.iter().enumerate() {
        if i > 0 {
            sql.push_str(", ");
        }
        sql.push_str(&dialect.quote_identifier(&a.column));
        sql.push_str(" = ");
        match &a.value {
            _ if a.default => sql.push_str("DEFAULT"),
            Some(v) => sql.push_str(&assigned_literal(dialect, a, v)),
            None => sql.push_str("NULL"),
        }
    }
    for (i, k) in key.iter().enumerate() {
        sql.push_str(if i == 0 { " WHERE " } else { " AND " });
        sql.push_str(&dialect.quote_identifier(&k.column));
        match &k.value {
            Some(v) => {
                sql.push_str(" = ");
                sql.push_str(&dialect.quote_string_literal(v));
            }
            None => sql.push_str(" IS NULL"),
        }
    }
    sql
}

/// Key of the row AFTER the `UPDATE`: the old one overlaid with the values
/// assigned to the PK columns (the user may have changed the key).
pub(crate) fn key_after(u: &RowUpdate) -> Vec<CellAssign> {
    u.key
        .iter()
        .map(|k| {
            u.set
                .iter()
                .find(|a| a.column == k.column)
                .unwrap_or(k)
                .clone()
        })
        .collect()
}

/// `SELECT *` of the rows with those PK keys, to re-read them after a save
/// from the grid: `WHERE (k1 = .. AND k2 = ..) OR (..)`.
pub(crate) fn rows_by_key_sql(
    dialect: &dyn Dialect,
    schema: &str,
    table: &str,
    keys: &[Vec<CellAssign>],
) -> String {
    let mut sql = format!(
        "SELECT * FROM {}.{} WHERE ",
        dialect.quote_identifier(schema),
        dialect.quote_identifier(table)
    );
    for (i, key) in keys.iter().enumerate() {
        if i > 0 {
            sql.push_str(" OR ");
        }
        sql.push('(');
        for (j, k) in key.iter().enumerate() {
            if j > 0 {
                sql.push_str(" AND ");
            }
            sql.push_str(&dialect.quote_identifier(&k.column));
            match &k.value {
                Some(v) => {
                    sql.push_str(" = ");
                    sql.push_str(&dialect.quote_string_literal(v));
                }
                None => sql.push_str(" IS NULL"),
            }
        }
        sql.push(')');
    }
    sql
}

/// `SELECT` of the first page with the requested filters and sorting.
pub(crate) fn table_sql(
    dialect: &dyn Dialect,
    schema: &str,
    table: &str,
    query: &TableQuery,
    limit: u64,
) -> String {
    let mut sql = format!(
        "SELECT * FROM {}.{}",
        dialect.quote_identifier(schema),
        dialect.quote_identifier(table)
    );
    for (i, f) in query.filters.iter().enumerate() {
        sql.push_str(if i == 0 { " WHERE " } else { " AND " });
        sql.push_str(&dialect.quote_identifier(&f.column));
        sql.push(' ');
        sql.push_str(f.op.sql());
        if f.op.takes_value() {
            sql.push(' ');
            sql.push_str(&dialect.quote_string_literal(&f.value));
        }
    }
    let typed = query.where_sql.trim();
    if !typed.is_empty() {
        sql.push_str(if query.filters.is_empty() {
            " WHERE "
        } else {
            " AND "
        });
        // In parentheses: a user's `OR` stays inside their condition.
        // The newline closes a possible trailing `-- comment`, which would
        // otherwise swallow ORDER BY and LIMIT.
        sql.push('(');
        sql.push_str(typed);
        sql.push_str("\n)");
    }
    for (i, o) in query.order_by.iter().enumerate() {
        sql.push_str(if i == 0 { " ORDER BY " } else { ", " });
        sql.push_str(&dialect.quote_identifier(&o.column));
        if o.desc {
            sql.push_str(" DESC");
        }
    }
    sql.push_str(&format!(" LIMIT {limit}"));
    sql
}

/// `SELECT` of a next page: the same as the first with `OFFSET` (accepted
/// as such by PG, MySQL and MariaDB). `offset` 0 = first page, identical to
/// `table_sql`.
pub(crate) fn table_page_sql(
    dialect: &dyn Dialect,
    schema: &str,
    table: &str,
    query: &TableQuery,
    limit: u64,
    offset: u64,
) -> String {
    let mut sql = table_sql(dialect, schema, table, query, limit);
    if offset > 0 {
        sql.push_str(&format!(" OFFSET {offset}"));
    }
    sql
}

#[cfg(test)]
mod tests {
    use super::*;
    use alamo_driver_mysql::MyDialect;
    use alamo_driver_postgres::PgDialect;

    fn q(order: Option<OrderBy>, filters: Vec<ColumnFilter>) -> TableQuery {
        TableQuery {
            order_by: order.into_iter().collect(),
            filters,
            where_sql: String::new(),
        }
    }

    #[test]
    fn next_page_appends_offset_after_limit() {
        let query = q(
            Some(OrderBy {
                column: "id".into(),
                desc: false,
            }),
            vec![],
        );
        let first = table_page_sql(&MyDialect::default(), "db", "t", &query, 1000, 0);
        assert_eq!(
            first,
            table_sql(&MyDialect::default(), "db", "t", &query, 1000)
        );
        let next = table_page_sql(&MyDialect::default(), "db", "t", &query, 1000, 2000);
        assert_eq!(
            next,
            "SELECT * FROM `db`.`t` ORDER BY `id` LIMIT 1000 OFFSET 2000"
        );
    }

    #[test]
    fn plain_page_has_no_where_nor_order() {
        let sql = table_sql(
            &PgDialect::default(),
            "public",
            "t",
            &TableQuery::default(),
            1000,
        );
        assert_eq!(sql, "SELECT * FROM \"public\".\"t\" LIMIT 1000");
    }

    #[test]
    fn filters_and_order_compose_with_pg_quoting() {
        let sql = table_sql(
            &PgDialect::default(),
            "public",
            "t",
            &q(
                Some(OrderBy {
                    column: "qty".into(),
                    desc: true,
                }),
                vec![
                    ColumnFilter {
                        column: "name".into(),
                        op: FilterOp::Like,
                        value: "al%".into(),
                    },
                    ColumnFilter {
                        column: "note".into(),
                        op: FilterOp::IsNull,
                        value: String::new(),
                    },
                ],
            ),
            1000,
        );
        assert_eq!(
            sql,
            "SELECT * FROM \"public\".\"t\" WHERE \"name\" LIKE 'al%' AND \"note\" IS NULL \
             ORDER BY \"qty\" DESC LIMIT 1000"
        );
    }

    #[test]
    fn literal_escaping_is_dialect_specific() {
        let f = |v: &str| {
            q(
                None,
                vec![ColumnFilter {
                    column: "c".into(),
                    op: FilterOp::Eq,
                    value: v.into(),
                }],
            )
        };
        // PG: doubled quote; with a backslash `E'…'` and doubled backslash,
        // valid even with standard_conforming_strings=off.
        let pg = table_sql(&PgDialect::default(), "s", "t", &f("l'a\\b"), 10);
        assert!(pg.contains("\"c\" = E'l''a\\\\b'"), "{pg}");
        // MySQL: the backslash doubles too, identifiers with backticks.
        let my = table_sql(&MyDialect::default(), "s", "t", &f("l'a\\b"), 10);
        assert!(my.contains("`c` = 'l''a\\\\b'"), "{my}");
    }

    fn a(column: &str, value: Option<&str>) -> CellAssign {
        CellAssign {
            column: column.into(),
            value: value.map(Into::into),
            default: false,
            numeric: false,
        }
    }

    fn num(column: &str, value: &str) -> CellAssign {
        CellAssign {
            numeric: true,
            ..a(column, Some(value))
        }
    }

    #[test]
    fn numeric_assignments_go_bare_in_set_and_values() {
        let d = MyDialect::default();
        let sql = update_sql(
            &d,
            "s",
            "t",
            &[num("flag", "1"), num("wide", "18446744073709551615")],
            &[num("id", "7")],
        );
        assert_eq!(
            sql,
            "UPDATE `s`.`t` SET `flag` = 1, `wide` = 18446744073709551615 WHERE `id` = '7'"
        );
        let sql = insert_sql(
            &d,
            "s",
            "t",
            &[num("id", "-3"), num("price", "1.50"), a("nome", Some("x"))],
        );
        assert_eq!(
            sql,
            "INSERT INTO `s`.`t` (`id`, `price`, `nome`) VALUES (-3, 1.50, 'x')"
        );
    }

    #[test]
    fn numeric_assignment_that_is_not_a_number_stays_quoted() {
        let d = MyDialect::default();
        for bad in ["", "1,5", "1e3", "0x1", " 1", "1.", ".5", "--1", "1; DROP"] {
            let sql = update_sql(&d, "s", "t", &[num("flag", bad)], &[a("id", Some("1"))]);
            assert!(sql.contains(&format!("`flag` = '{bad}'")), "{sql}");
        }
        assert!(is_number_literal("0"));
        assert!(is_number_literal("-12.345"));
    }

    #[test]
    fn update_set_default_uses_the_keyword() {
        let d = CellAssign {
            column: "status".into(),
            value: Some("ignored".into()),
            default: true,
            numeric: false,
        };
        let sql = update_sql(&MyDialect::default(), "s", "t", &[d], &[a("id", Some("1"))]);
        assert_eq!(
            sql,
            "UPDATE `s`.`t` SET `status` = DEFAULT WHERE `id` = '1'"
        );
    }

    #[test]
    fn insert_lists_columns_null_values_and_default() {
        let d = CellAssign {
            column: "status".into(),
            value: None,
            default: true,
            numeric: false,
        };
        let sql = insert_sql(
            &PgDialect::default(),
            "public",
            "t",
            &[a("name", Some("it's")), a("note", None), d],
        );
        assert_eq!(
            sql,
            "INSERT INTO \"public\".\"t\" (\"name\", \"note\", \"status\") \
             VALUES ('it''s', NULL, DEFAULT)"
        );
    }

    #[test]
    fn insert_without_columns_changes_form_per_dialect() {
        assert_eq!(
            insert_sql(&PgDialect::default(), "public", "t", &[]),
            "INSERT INTO \"public\".\"t\" DEFAULT VALUES"
        );
        assert_eq!(
            insert_sql(&MyDialect::default(), "db", "t", &[]),
            "INSERT INTO `db`.`t` () VALUES ()"
        );
    }

    #[test]
    fn reread_inserted_by_key_or_last_insert_id() {
        let d = &MyDialect::default();
        let id = vec!["id".to_string()];
        assert_eq!(
            reread_inserted_sql(d, "s", "t", &[a("name", Some("x"))], &id),
            Some("SELECT * FROM `s`.`t` WHERE `id` = LAST_INSERT_ID()".into())
        );
        assert_eq!(
            reread_inserted_sql(d, "s", "t", &[a("id", Some("7")), a("name", None)], &id),
            Some("SELECT * FROM `s`.`t` WHERE `id` = '7'".into())
        );
        let two = vec!["a".to_string(), "b".to_string()];
        assert_eq!(
            reread_inserted_sql(d, "s", "t", &[a("a", Some("1")), a("b", Some("2"))], &two),
            Some("SELECT * FROM `s`.`t` WHERE `a` = '1' AND `b` = '2'".into())
        );
        assert_eq!(
            reread_inserted_sql(d, "s", "t", &[a("a", Some("1"))], &two),
            None
        );
        assert_eq!(reread_inserted_sql(d, "s", "t", &[], &[]), None);
    }

    #[test]
    fn delete_by_composite_key() {
        let sql = delete_sql(
            &PgDialect::default(),
            "public",
            "t",
            &[a("a", Some("1")), a("b", None)],
        );
        assert_eq!(
            sql,
            "DELETE FROM \"public\".\"t\" WHERE \"a\" = '1' AND \"b\" IS NULL"
        );
    }

    #[test]
    fn table_write_deserializes_with_kind() {
        let w: Vec<TableWrite> = serde_json::from_str(
            r#"[{"kind":"update","set":[{"column":"n","value":"1"}],"key":[{"column":"id","value":"2"}]},
                {"kind":"insert","values":[{"column":"n","value":null,"default":true}]}]"#,
        )
        .unwrap();
        let d = &MyDialect::default();
        assert_eq!(
            w[0].sql(d, "s", "t"),
            "UPDATE `s`.`t` SET `n` = '1' WHERE `id` = '2'"
        );
        assert_eq!(
            w[1].sql(d, "s", "t"),
            "INSERT INTO `s`.`t` (`n`) VALUES (DEFAULT)"
        );
    }

    #[test]
    fn update_composes_set_and_pk_where() {
        let sql = update_sql(
            &PgDialect::default(),
            "public",
            "t",
            &[a("name", Some("it's")), a("note", None)],
            &[a("id", Some("5"))],
        );
        assert_eq!(
            sql,
            "UPDATE \"public\".\"t\" SET \"name\" = 'it''s', \"note\" = NULL \
             WHERE \"id\" = '5'"
        );
    }

    #[test]
    fn update_composite_pk_and_mysql_quoting() {
        let sql = update_sql(
            &MyDialect::default(),
            "s",
            "t",
            &[a("v", Some("a\\b"))],
            &[a("k1", Some("1")), a("k2", Some("x"))],
        );
        assert_eq!(
            sql,
            "UPDATE `s`.`t` SET `v` = 'a\\\\b' WHERE `k1` = '1' AND `k2` = 'x'"
        );
    }

    #[test]
    fn update_null_key_becomes_is_null() {
        // The PK is never NULL, but the generator stays correct if one day
        // the editing key includes nullable columns.
        let sql = update_sql(
            &PgDialect::default(),
            "s",
            "t",
            &[a("v", Some("x"))],
            &[a("k", None)],
        );
        assert!(sql.ends_with("WHERE \"k\" IS NULL"), "{sql}");
    }

    #[test]
    fn reread_by_key_with_or_between_rows() {
        let sql = rows_by_key_sql(
            &MyDialect::default(),
            "s",
            "t",
            &[
                vec![a("k1", Some("1")), a("k2", Some("x"))],
                vec![a("k1", Some("2")), a("k2", None)],
            ],
        );
        assert_eq!(
            sql,
            "SELECT * FROM `s`.`t` WHERE (`k1` = '1' AND `k2` = 'x') OR (`k1` = '2' AND `k2` IS NULL)"
        );
    }

    #[test]
    fn the_key_after_the_update_follows_the_changed_pk() {
        let u = RowUpdate {
            set: vec![a("v", Some("z")), a("k2", Some("y"))],
            key: vec![a("k1", Some("1")), a("k2", Some("x"))],
        };
        let k = key_after(&u);
        assert_eq!(k[0].value.as_deref(), Some("1"));
        assert_eq!(k[1].value.as_deref(), Some("y"));
    }

    #[test]
    fn is_null_ignores_the_value() {
        let sql = table_sql(
            &PgDialect::default(),
            "s",
            "t",
            &q(
                None,
                vec![ColumnFilter {
                    column: "c".into(),
                    op: FilterOp::IsNotNull,
                    value: "ignored".into(),
                }],
            ),
            10,
        );
        assert!(sql.ends_with("WHERE \"c\" IS NOT NULL LIMIT 10"), "{sql}");
    }

    fn typed(where_sql: &str, filters: Vec<ColumnFilter>) -> TableQuery {
        TableQuery {
            where_sql: where_sql.into(),
            ..q(None, filters)
        }
    }

    #[test]
    fn typed_where_goes_in_and_with_the_chips() {
        let chip = ColumnFilter {
            column: "id".into(),
            op: FilterOp::Gt,
            value: "5".into(),
        };
        let pg = table_sql(
            &PgDialect::default(),
            "s",
            "t",
            &typed("name LIKE 'a%' OR name IS NULL", vec![chip.clone()]),
            10,
        );
        assert_eq!(
            pg,
            "SELECT * FROM \"s\".\"t\" WHERE \"id\" > '5' AND (name LIKE 'a%' OR name IS NULL\n) LIMIT 10"
        );
        let my = table_sql(
            &MyDialect::default(),
            "s",
            "t",
            &typed("  x = 1 ", vec![]),
            10,
        );
        assert_eq!(my, "SELECT * FROM `s`.`t` WHERE (x = 1\n) LIMIT 10");
    }

    #[test]
    fn trailing_comment_does_not_swallow_limit() {
        let sql = table_sql(
            &PgDialect::default(),
            "s",
            "t",
            &typed("x = 1 -- only the first", vec![]),
            10,
        );
        assert!(sql.ends_with("-- only the first\n) LIMIT 10"), "{sql}");
    }

    #[test]
    fn blank_typed_where_adds_nothing() {
        let sql = table_sql(&PgDialect::default(), "s", "t", &typed(" \n ", vec![]), 10);
        assert_eq!(sql, "SELECT * FROM \"s\".\"t\" LIMIT 10");
    }

    #[test]
    fn order_by_several_columns_in_priority_order() {
        let query = TableQuery {
            order_by: vec![
                OrderBy {
                    column: "data".into(),
                    desc: true,
                },
                OrderBy {
                    column: "id".into(),
                    desc: false,
                },
            ],
            ..Default::default()
        };
        let pg = table_sql(&PgDialect::default(), "s", "t", &query, 10);
        assert_eq!(
            pg,
            "SELECT * FROM \"s\".\"t\" ORDER BY \"data\" DESC, \"id\" LIMIT 10"
        );
        let my = table_sql(&MyDialect::default(), "s", "t", &query, 10);
        assert_eq!(
            my,
            "SELECT * FROM `s`.`t` ORDER BY `data` DESC, `id` LIMIT 10"
        );
    }

    #[test]
    fn order_by_accepts_the_old_single_object_and_null() {
        let one: TableQuery =
            serde_json::from_str(r#"{"order_by":{"column":"id","desc":true},"filters":[]}"#)
                .unwrap();
        assert_eq!(one.order_by.len(), 1);
        assert!(one.order_by[0].desc);
        let none: TableQuery = serde_json::from_str(r#"{"order_by":null,"filters":[]}"#).unwrap();
        assert!(none.order_by.is_empty());
        let many: TableQuery =
            serde_json::from_str(r#"{"order_by":[{"column":"a"},{"column":"b","desc":true}]}"#)
                .unwrap();
        assert_eq!(many.order_by.len(), 2);
        let absent: TableQuery = serde_json::from_str("{}").unwrap();
        assert!(absent.order_by.is_empty());
    }
}
